#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;



// Hàm nhập thông tin sinh viên
Student inputStudent() {
    Student s;
    cout << "Nhap ten: ";
    getline(cin, s.name);
    cout << "Nhap tuoi: ";
    cin >> s.age;
    cout << "Nhap GPA: ";
    cin >> s.gpa;
    cin.ignore(); // bỏ ký tự xuống dòng
    return s;
}

// Hàm in thông tin sinh viên
void printStudent(const Student &s) {
    cout << "Ten: " << s.name
         << ", Tuoi: " << s.age
         << ", GPA: " << s.gpa << endl;
}

int main() {
    int n;
    cout << "Nhap so luong sinh vien: ";
    cin >> n;
    cin.ignore();

    vector<Student> students;
    for (int i = 0; i < n; i++) {
        cout << "Sinh vien thu " << i+1 << ":" << endl;
        students.push_back(inputStudent());
    }

    // Sắp xếp theo GPA giảm dần
    sort(students.begin(), students.end(), [](const Student &a, const Student &b) {
        return a.gpa > b.gpa;
    });

    cout << "\nDanh sach sinh vien sau khi sap xep theo GPA:\n";
    for (const auto &s : students) {
        printStudent(s);
    }

    return 0;
}
